policies.remediation:
ntp server {NTP_SERVER_1} prefer
ntp server {NTP_SERVER_2}
! Replace {NTP_SERVER_1} and {NTP_SERVER_2} with your NTP server IPs

policies.remediation_juniper:
set system ntp server {NTP_SERVER_1} prefer
set system ntp server {NTP_SERVER_2}
! Replace {NTP_SERVER_1} and {NTP_SERVER_2} with your NTP server IPs

policies.remediation:
snmp-server group {SNMP_GROUP} v3 auth
snmp-server user {SNMP_USER} {SNMP_GROUP} v3 auth sha {SNMP_AUTH_PASS}
! Replace {SNMP_GROUP}, {SNMP_USER}, {SNMP_AUTH_PASS} with your values

logging host {SYSLOG_SERVER}
logging trap informational
! Replace {SYSLOG_SERVER} with your syslog server IP

hostname {SITE}-{ROLE}-{NN}
! Example: hostname NYC-SW-01
! Format: SITE(2-6 chars)-ROLE(2-4 chars)-NN(2 digits)

! On interfaces facing untrusted networks:
interface {INTERFACE}
 no cdp enable

! Disable on each routed interface:
interface {INTERFACE}
 no ip proxy-arp

! Apply QoS policy on uplink interfaces:
interface {UPLINK_INTERFACE}
 service-policy input {QOS_POLICY_NAME}
! Replace {UPLINK_INTERFACE} and {QOS_POLICY_NAME} with your values

interface {GATEWAY_INTERFACE}
 standby {GROUP_ID} ip {VIRTUAL_IP}
 standby {GROUP_ID} priority {PRIORITY}
 standby {GROUP_ID} preempt
! Replace placeholders with your HSRP group values

! Apply on all access/edge interfaces:
interface {ACCESS_INTERFACE}
 spanning-tree guard root

! Disable CDP on access/edge interfaces:
interface {ACCESS_INTERFACE}
 no cdp enable

vlan {MGMT_VLAN_ID}
 name MGMT
interface vlan {MGMT_VLAN_ID}
 ip address {MGMT_IP} {MGMT_MASK}
 no shutdown

! Investigate interfaces with errors:
show interfaces {INTERFACE}
! Common causes: duplex mismatch, bad cable, SFP issue

aaa accounting exec default start-stop group {TACACS_GROUP}
aaa accounting commands 15 default start-stop group {TACACS_GROUP}
! Replace {TACACS_GROUP} with your TACACS+ server group name

tacacs-server host {TACACS_SERVER} key {TACACS_KEY}
aaa group server tacacs+ TACACS-GROUP
 server {TACACS_SERVER}
aaa authentication login default group TACACS-GROUP local
! Replace {TACACS_SERVER} and {TACACS_KEY} with your values
